def random_add_speckle_noise_pt(img, speckle_std):
    std_range = speckle_std
    std_l = std_range[0]
    std_r = std_range[1]
    mean=0
    std=random.uniform(std_l/255.,std_r/255.)
    gauss=torch.normal(mean=mean,std=std,size=img.size()).to(img.device)
    noisy=img+gauss*img
    noisy=torch.clamp(noisy,0,1)
    return noisy

